#!/bin/sh
# Vaultwarden init — declarative DB-config injection.
# Mirrors the bb-sec_authelia/src/templates/init.sh.tpl pattern (entrypoint
# override → assert DB state → exec upstream). Rendered by _shared/engine.nix
# (diegonmarcos.com substituted from build.json.domain) → dist/configs/init.sh,
# mounted read-only at /config/init.sh and run as the container entrypoint.
#
# WHY: Vaultwarden gates the TOTP / premium feature *display* behind
#   emailVerified = !mail_enabled() || verified_at.is_some()   (src/db/models/user.rs)
# SMTP stays enabled (new users still verify via email link). This re-asserts
# the operator account's verified_at idempotently on every boot, so the
# operator's stored TOTP codes render in the web vault without a manual click.
#
# FAILSAFE: every step tolerates failure and we ALWAYS exec /start.sh last —
# a DB hiccup can never take the password vault offline.
set -u

DB="/data/db.sqlite3"
OPERATOR="me@diegonmarcos.com"   # data-driven: diegonmarcos.com ← build.json.domain

if command -v sqlite3 >/dev/null 2>&1 && [ -f "$DB" ]; then
  # Reuse the row's own created_at as the verified_at value: it is guaranteed
  # to be a timestamp Vaultwarden itself wrote and can parse, so we never risk
  # a datetime-format mismatch. Guarded by `verified_at IS NULL` → idempotent.
  if sqlite3 "$DB" \
       "UPDATE users SET verified_at = created_at
        WHERE email = '$OPERATOR' AND verified_at IS NULL;" 2>/dev/null; then
    echo "[vw-init] verified_at asserted for $OPERATOR (idempotent)"
  else
    echo "[vw-init] WARNING: verified_at update failed (non-fatal)"
  fi
else
  echo "[vw-init] sqlite3 or $DB absent — skipping (non-fatal: first boot / no DB yet)"
fi

echo "[vw-init] handing off to upstream entrypoint /start.sh"
exec /start.sh
